<section class="container section page-top"><div class="dash-layout"><?php require __DIR__.'/../partials/side_nav.php';?><div class="dash-main"><div class="eyebrow">ADMIN CATEGORIES</div><h1 class="page-title">Quản lý <em>danh mục</em></h1><div class="dashboard-highlight"><div class="panel"><h2>Danh sách danh mục</h2><div class="table-wrap"><table><thead><tr><th>Tên</th><th>Slug</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['slug'])?></td><td><?=$c['status']?'Hiển thị':'Đang ẩn'?></td><td class="action-cell"><a class="btn btn-outline btn-sm" href="<?=h(url('admin_categories',['id'=>$c['id']]))?>">Sửa</a><form method="post" action="<?=h(url('admin_categories'))?>"><?php csrf_field();?><input type="hidden" name="action" value="admin_category_toggle"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn btn-ghost btn-sm"><?=$c['status']?'Ẩn':'Bật'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div>
